    Arrangement arr;
    for (const Segment2d& seg : segments) {
        Point_2 p1(seg.p1().x(), seg.p1().y());
        Point_2 p2(seg.p2().x(), seg.p2().y());
        Segment_2 cgalSeg(p1, p2);
        CGAL::insert(arr, cgalSeg);
    }
    return arr;
}

